mapper.select:
SELECT COUNT(1)
  FROM PHOTO_POSTS p
 WHERE #{contentType} = 'PHOTO'
   AND p.POST_ID = #{contentId}
   AND UPPER(NVL(p.VISIBILITY_TYPE, 'PRIVATE')) IN ('FRIENDS', 'PUBLIC', 'MOYO', 'GLOBAL')
   AND p.CREATED_BY <> #{userId}

mapper.update:
DECLARE
    v_table_count NUMBER := 0;
    v_constraint_count NUMBER := 0;
BEGIN
    SELECT COUNT(*)
      INTO v_table_count
      FROM USER_TABLES
     WHERE TABLE_NAME = 'CONTENT_SHARES';

    IF v_table_count > 0 THEN
        SELECT COUNT(*)
          INTO v_constraint_count
          FROM USER_CONSTRAINTS
         WHERE TABLE_NAME = 'CONTENT_SHARES'
           AND CONSTRAINT_NAME = 'CK_CONTENT_SHARE_CONTENT';

        IF v_constraint_count > 0 THEN
            EXECUTE IMMEDIATE 'ALTER TABLE CONTENT_SHARES DROP CONSTRAINT CK_CONTENT_SHARE_CONTENT';
        END IF;

        EXECUTE IMMEDIATE 'ALTER TABLE CONTENT_SHARES ADD CONSTRAINT CK_CONTENT_SHARE_CONTENT CHECK (CONTENT_TYPE IN (''NOTE'',''PHOTO'',''ALBUM'',''BOARD'',''EVENT'',''CALENDAR'',''POLL'',''FILE''))';
    END IF;
END;

UPDATE CONTENT_SHARES s
   SET s.ACTIVE_YN = 'N',
       s.UPDATED_AT = SYSDATE
 WHERE s.SHARE_ID = #{shareId}
   AND s.OWNER_ID = #{userId}
   AND s.ACTIVE_YN = 'Y'

mapper.delete:
DELETE FROM CONTENT_SHARES
WHERE CONTENT_TYPE = #{contentType}
  AND CONTENT_ID = #{contentId}
